import React from "react";
import ReactDOM from "react-dom/client";
import { Theme } from "@astryxdesign/core";
import { neutralTheme } from "@astryxdesign/theme-neutral";
import { App } from "./App";
import "./styles/global.css";

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    <Theme theme={neutralTheme} mode="system">
      <App />
    </Theme>
  </React.StrictMode>
);

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html, body, #root {
  height: 100%;
  width: 100%;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

import { Playground } from "./pages/Playground";

export function App() {
  return <Playground />;
}

import { useState, useEffect } from "react";

export interface Policy {
  id: number;
  name: string;
  description: string | null;
  content: string;
  created_at: string;
  updated_at: string;
}

export function usePolicies() {
  const [policies, setPolicies] = useState<Policy[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchPolicies() {
      try {
        const response = await fetch("/api/policies");
        if (!response.ok) {
          throw new Error(`Failed to fetch policies: ${response.statusText}`);
        }
        const data = await response.json();
        setPolicies(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    }

    fetchPolicies();
  }, []);

  return { policies, loading, error };
}

import { useState, useEffect } from "react";

export interface Resource {
  id: number;
  type: string;
  name: string;
  attributes: Record<string, unknown>;
}

export function useResources(typeFilter?: string) {
  const [resources, setResources] = useState<Resource[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchResources() {
      try {
        const url = typeFilter
          ? `/api/resources?type=${encodeURIComponent(typeFilter)}`
          : "/api/resources";
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error(`Failed to fetch resources: ${response.statusText}`);
        }
        const data = await response.json();
        setResources(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    }

    fetchResources();
  }, [typeFilter]);

  return { resources, loading, error };
}

import { useState, useEffect } from "react";

export interface Role {
  id: number;
  name: string;
  permissions: string[];
}

export function useRoles() {
  const [roles, setRoles] = useState<Role[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function fetchRoles() {
      try {
        const response = await fetch("/api/roles");
        if (!response.ok) {
          throw new Error(`Failed to fetch roles: ${response.statusText}`);
        }
        const data = await response.json();
        setRoles(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : "Unknown error");
      } finally {
        setLoading(false);
      }
    }

    fetchRoles();
  }, []);

  return { roles, loading, error };
}

export { usePolicies } from "./usePolicies";
export { useResources } from "./useResources";
export { useRoles } from "./useRoles";

import React from "react";
import { Button as AstryxButton } from "@astryxdesign/core";

export interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: "primary" | "secondary" | "ghost";
  size?: "sm" | "md" | "lg";
}

export function Button({
  variant = "primary",
  size = "md",
  children,
  ...props
}: ButtonProps) {
  return (
    <AstryxButton
      {...props}
      data-variant={variant}
      data-size={size}
    >
      {children}
    </AstryxButton>
  );
}

import React from "react";
import { Button } from "./Button";
import type { Policy } from "../../hooks/usePolicies";

export interface PolicyListProps {
  policies: Policy[];
  selectedPolicyId?: number;
  onSelectPolicy: (policy: Policy) => void;
  onNewPolicy: () => void;
  loading?: boolean;
}

export function PolicyList({
  policies,
  selectedPolicyId,
  onSelectPolicy,
  onNewPolicy,
  loading = false,
}: PolicyListProps) {
  return (
    <div className="policy-list">
      <div className="policy-list-header">
        <h2>Policies</h2>
        <Button onClick={onNewPolicy} size="sm">
          + New Policy
        </Button>
      </div>
      <div className="policy-list-content">
        {loading ? (
          <div className="policy-list-loading">Loading...</div>
        ) : policies.length === 0 ? (
          <div className="policy-list-empty">No policies found</div>
        ) : (
          <ul className="policy-list-items">
            {policies.map((policy) => (
              <li
                key={policy.id}
                className={`policy-item ${
                  selectedPolicyId === policy.id ? "selected" : ""
                }`}
                onClick={() => onSelectPolicy(policy)}
              >
                <span className="policy-name">{policy.name}</span>
                {policy.description && (
                  <span className="policy-description">{policy.description}</span>
                )}
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

import React, { useState } from "react";

export interface Tab {
  id: string;
  label: string;
  content: React.ReactNode;
}

export interface TabsProps {
  tabs: Tab[];
  defaultTab?: string;
}

export function Tabs({ tabs, defaultTab }: TabsProps) {
  const [activeTab, setActiveTab] = useState(
    defaultTab || tabs[0]?.id || ""
  );

  const activeContent = tabs.find((tab) => tab.id === activeTab)?.content;

  return (
    <div className="tabs">
      <div className="tabs-header">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            className={`tab-button ${activeTab === tab.id ? "active" : ""}`}
            onClick={() => setActiveTab(tab.id)}
          >
            {tab.label}
          </button>
        ))}
      </div>
      <div className="tabs-content">{activeContent}</div>
    </div>
  );
}

import React from "react";
import type { Policy } from "../../hooks/usePolicies";

export interface PolicyEditorProps {
  policy: Policy | null;
  onSave: (policy: Policy) => void;
}

export function PolicyEditor({ policy, onSave }: PolicyEditorProps) {
  const [content, setContent] = React.useState(policy?.content || "");

  React.useEffect(() => {
    setContent(policy?.content || "");
  }, [policy]);

  if (!policy) {
    return (
      <div className="policy-editor-empty">
        <p>Select a policy to edit or create a new one</p>
      </div>
    );
  }

  return (
    <div className="policy-editor">
      <div className="policy-editor-header">
        <h3>{policy.name}</h3>
      </div>
      <textarea
        className="policy-editor-textarea"
        value={content}
        onChange={(e) => setContent(e.target.value)}
        placeholder="Enter Cedar policy here..."
      />
    </div>
  );
}

import React from "react";

export interface EvaluationResult {
  decision: "Permit" | "Deny";
  reason?: string;
  errors?: string[];
}

export interface TestPanelProps {
  onEvaluate: () => Promise<EvaluationResult>;
  result?: EvaluationResult;
}

export function TestPanel({ onEvaluate, result }: TestPanelProps) {
  return (
    <div className="test-panel">
      <div className="test-panel-header">
        <h3>Test Panel</h3>
      </div>
      <div className="test-panel-content">
        <button onClick={onEvaluate} className="evaluate-button">
          Run Evaluation
        </button>
        {result && (
          <div className={`evaluation-result ${result.decision.toLowerCase()}`}>
            <h4>Result: {result.decision}</h4>
            {result.reason && <p>{result.reason}</p>}
            {result.errors && result.errors.length > 0 && (
              <div className="errors">
                <h5>Errors:</h5>
                <ul>
                  {result.errors.map((error, index) => (
                    <li key={index}>{error}</li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import React from "react";

export interface ResultDisplayProps {
  result?: {
    decision: "Permit" | "Deny";
    reason?: string;
    errors?: string[];
  };
}

export function ResultDisplay({ result }: ResultDisplayProps) {
  if (!result) {
    return (
      <div className="result-display">
        <div className="result-empty">
          <p>Run a test to see results</p>
        </div>
      </div>
    );
  }

  return (
    <div className={`result-display ${result.decision.toLowerCase()}`}>
      <div className="result-header">
        <h3>Evaluation Result</h3>
        <span className={`decision-badge ${result.decision.toLowerCase()}`}>
          {result.decision}
        </span>
      </div>
      {result.reason && (
        <div className="result-reason">
          <h4>Reason</h4>
          <p>{result.reason}</p>
        </div>
      )}
      {result.errors && result.errors.length > 0 && (
        <div className="result-errors">
          <h4>Errors</h4>
          <ul>
            {result.errors.map((error, index) => (
              <li key={index}>{error}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

import React, { useState } from "react";
import { PolicyList } from "../components/ui/Sidebar";
import { Tabs } from "../components/ui/Tabs";
import { PolicyEditor } from "../components/PolicyEditor";
import { TestPanel } from "../components/TestPanel";
import { ResultDisplay } from "../components/ResultDisplay";
import { usePolicies } from "../hooks/usePolicies";
import type { Policy } from "../hooks/usePolicies";

export function Playground() {
  const { policies, loading: policiesLoading, error: policiesError } = usePolicies();
  const [selectedPolicy, setSelectedPolicy] = useState<Policy | null>(null);
  const [evaluationResult, setEvaluationResult] = useState<
    | { decision: "Permit" | "Deny"; reason?: string; errors?: string[] }
    | undefined
  >(undefined);

  const handleSelectPolicy = (policy: Policy) => {
    setSelectedPolicy(policy);
  };

  const handleNewPolicy = () => {
    setSelectedPolicy({
      id: 0,
      name: "New Policy",
      description: "",
      content: "",
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    });
  };

  const handleEvaluate = async () => {
    try {
      const response = await fetch("/api/evaluate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          policy_id: selectedPolicy?.id,
          content: selectedPolicy?.content,
        }),
      });

      if (!response.ok) {
        throw new Error(`Evaluation failed: ${response.statusText}`);
      }

      const result = await response.json();
      setEvaluationResult(result);
    } catch (error) {
      setEvaluationResult({
        decision: "Deny",
        reason: "Evaluation failed",
        errors: [error instanceof Error ? error.message : "Unknown error"],
      });
    }
  };

  const editorTab = {
    id: "editor",
    label: "Policy Editor",
    content: <PolicyEditor policy={selectedPolicy} onSave={setSelectedPolicy} />,
  };

  const testTab = {
    id: "test",
    label: "Test Panel",
    content: (
      <TestPanel onEvaluate={handleEvaluate} result={evaluationResult} />
    ),
  };

  return (
    <div className="playground">
      <aside className="playground-sidebar">
        <PolicyList
          policies={policies}
          selectedPolicyId={selectedPolicy?.id}
          onSelectPolicy={handleSelectPolicy}
          onNewPolicy={handleNewPolicy}
          loading={policiesLoading}
        />
      </aside>
      <main className="playground-main">
        <Tabs tabs={[editorTab, testTab]} defaultTab="editor" />
      </main>
      <footer className="playground-footer">
        <ResultDisplay result={evaluationResult} />
      </footer>
    </div>
  );
}

