/* Playground Layout */
.playground {
  display: grid;
  grid-template-columns: 280px 1fr;
  grid-template-rows: 1fr auto;
  height: 100%;
  width: 100%;
}

.playground-sidebar {
  grid-row: 1 / -1;
  border-right: 1px solid var(--color-border-default, #e5e7eb);
  overflow-y: auto;
  background: var(--color-background-secondary, #f9fafb);
}

.playground-main {
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.playground-footer {
  border-top: 1px solid var(--color-border-default, #e5e7eb);
  background: var(--color-background-secondary, #f9fafb);
  max-height: 200px;
  overflow-y: auto;
}

/* Policy List */
.policy-list {
  padding: 16px;
  height: 100%;
  display: flex;
  flex-direction: column;
}

.policy-list-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16px;
}

.policy-list-header h2 {
  font-size: 18px;
  font-weight: 600;
}

.policy-list-content {
  flex: 1;
  overflow-y: auto;
}

.policy-list-items {
  list-style: none;
}

.policy-item {
  padding: 12px;
  border-radius: 8px;
  cursor: pointer;
  margin-bottom: 4px;
  transition: background-color 150ms;
}

.policy-item:hover {
  background: var(--color-background-tertiary, #f3f4f6);
}

.policy-item.selected {
  background: var(--color-accent, #6366f1);
  color: white;
}

.policy-name {
  display: block;
  font-weight: 500;
}

.policy-description {
  display: block;
  font-size: 12px;
  opacity: 0.7;
  margin-top: 4px;
}

/* Tabs */
.tabs {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.tabs-header {
  display: flex;
  gap: 4px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--color-border-default, #e5e7eb);
  background: var(--color-background-secondary, #f9fafb);
}

.tab-button {
  padding: 8px 16px;
  border: none;
  background: transparent;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: var(--color-text-secondary, #6b7280);
  border-bottom: 2px solid transparent;
  transition: all 150ms;
}

.tab-button:hover {
  color: var(--color-text-primary, #111827);
}

.tab-button.active {
  color: var(--color-accent, #6366f1);
  border-bottom-color: var(--color-accent, #6366f1);
}

.tabs-content {
  flex: 1;
  overflow: auto;
  padding: 16px;
}

/* Policy Editor */
.policy-editor {
  height: 100%;
  display: flex;
  flex-direction: column;
}

.policy-editor-header {
  margin-bottom: 12px;
}

.policy-editor-header h3 {
  font-size: 16px;
  font-weight: 600;
}

.policy-editor-textarea {
  flex: 1;
  width: 100%;
  min-height: 200px;
  padding: 12px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 14px;
  border: 1px solid var(--color-border-default, #e5e7eb);
  border-radius: 8px;
  resize: none;
}

.policy-editor-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--color-text-secondary, #6b7280);
}

/* Test Panel */
.test-panel {
  height: 100%;
}

.test-panel-header {
  margin-bottom: 12px;
}

.test-panel-header h3 {
  font-size: 16px;
  font-weight: 600;
}

.evaluate-button {
  padding: 8px 16px;
  background: var(--color-accent, #6366f1);
  color: white;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-weight: 500;
  transition: opacity 150ms;
}

.evaluate-button:hover {
  opacity: 0.9;
}

.evaluation-result {
  margin-top: 16px;
  padding: 12px;
  border-radius: 8px;
}

.evaluation-result.permit {
  background: #dcfce7;
  border: 1px solid #86efac;
}

.evaluation-result.deny {
  background: #fee2e2;
  border: 1px solid #fca5a5;
}

/* Result Display */
.result-display {
  padding: 16px;
}

.result-empty {
  text-align: center;
  color: var(--color-text-secondary, #6b7280);
}

.result-header {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 12px;
}

.result-header h3 {
  font-size: 16px;
  font-weight: 600;
}

.decision-badge {
  padding: 4px 12px;
  border-radius: 9999px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
}

.decision-badge.permit {
  background: #86efac;
  color: #166534;
}

.decision-badge.deny {
  background: #fca5a5;
  color: #991b1b;
}

.result-reason,
.result-errors {
  margin-top: 8px;
}

.result-reason h4,
.result-errors h4 {
  font-size: 14px;
  font-weight: 500;
  margin-bottom: 4px;
}

.result-errors ul {
  list-style: disc;
  padding-left: 20px;
  color: #dc2626;
}

/* Mobile Responsive */
@media (max-width: 767px) {
  .playground {
    grid-template-columns: 1fr;
    grid-template-rows: auto 1fr auto;
  }

  .playground-sidebar {
    grid-row: auto;
    max-height: 200px;
    border-right: none;
    border-bottom: 1px solid var(--color-border-default, #e5e7eb);
  }
}

